  "Model unloaded": "Модель выгружена",
  "Tokens": "Токенов",
  "seconds": "секунд",
  "tokens/s": "токенов/с",
  "None": "Нет",
  "All": "Все",
  "Reset": "Сброс",
  "No changes": "Нет изменений",
  "Changes saved": "Изменения сохранены",
  "Something went wrong": "Что-то пошло не так",
  "Please try again": "Пожалуйста, попробуйте снова",
  "Copied to clipboard": "Скопировано в буфер обмена",
  "Code copied": "Код скопирован",
  "Message copied": "Сообщение скопировано",
  "Set the API Key if you are using --api-key option for the server.": "Укажите API-ключ, если вы используете опцию --api-key для сервера.",
  "Parse PDF as image instead of text. Automatically falls back to text processing for non-vision models.": "Обрабатывать PDF как изображение вместо текста. Автоматически переключается на текстовую обработку для моделей без поддержки изображений.",
  "Render user messages using markdown formatting in the chat.": "Отображать сообщения пользователя с форматированием Markdown в чате.",
  "Disable automatic scrolling while messages stream so you can control the viewport position manually.": "Отключить автоматическую прокрутку во время потока сообщений, чтобы управлять положением вручную.",
  "Display quantization badges (e.g. Q8_0, Q4_K_M) next to model names throughout the interface.": "Отображать бейджи квантизации (например, Q8_0, Q4_K_M) рядом с именами моделей по всему интерфейсу.",
  "DRY sampling reduces repetition in generated text even across long contexts. This parameter sets the DRY sampling multiplier.": "Сэмплирование DRY уменьшает повторения в генерируемом тексте даже на длинных контекстах. Этот параметр задаёт множитель сэмплирования DRY.",
  "DRY sampling reduces repetition in generated text even across long contexts. This parameter sets the DRY sampling base value.": "Сэмплирование DRY уменьшает повторения в генерируемом тексте даже на длинных контекстах. Этот параметр задаёт базовое значение сэмплирования DRY.",
  "DRY sampling reduces repetition in generated text even across long contexts. This parameter sets the allowed length for DRY sampling.": "Сэмплирование DRY уменьшает повторения в генерируемом тексте даже на длинных контекстах. Этот параметр задаёт разрешённую длину для сэмплирования DRY.",
  "DRY sampling reduces repetition in generated text even across long contexts. This parameter sets DRY penalty for the last n tokens.": "Сэмплирование DRY уменьшает повторения в генерируемом тексте даже на длинных контекстах. Этот параметр задаёт штраф DRY за последние n токенов.",
  "No tools available": "Нет доступных инструментов",
  "Conversations": "Беседы",
  "Download your conversations as a ZIP of JSONL files. This includes all messages, attachments, and conversation history.": "Скачайте ваши беседы в виде ZIP-архива с файлами JSONL. Включает все сообщения, вложения и историю бесед.",
  "Export conversations": "Экспорт бесед",
  "Import one or more conversations from a previously exported ZIP or JSONL file. This will merge with your existing conversations.": "Импортируйте одну или несколько бесед из ранее экспортированного ZIP или JSONL файла. Они будут объединены с существующими беседами.",
