  "CSS injected into the page at runtime. Set it here, or ship it server side via the --ui-config customCss field.": "CSS inyectado en la página en tiempo de ejecución. Configúralo aquí o mediante --ui-config customCss.",
  "Custom JSON parameters to send to the API. Must be valid JSON format.": "Parámetros JSON personalizados para enviar a la API. Debe ser JSON válido.",
  "Configure MCP servers as a JSON list. Use the form in the MCP Client settings section to edit.": "Configura servidores MCP como lista JSON. Usa el formulario en la sección MCP Client.",
  "Expand thought process by default when generating messages.": "Expandir proceso de pensamiento por defecto al generar mensajes.",
  "Render the reasoning/thinking block content as formatted Markdown instead of plain text.": "Renderizar el bloque de razonamiento como Markdown formateado en vez de texto plano.",
  "Strip thinking from previous messages before sending. When off, thinking is sent back via the reasoning_content field so the model sees its own chain-of-thought across turns.": "Eliminar pensamiento de mensajes anteriores antes de enviar. Desactivado: el pensamiento se envía vía reasoning_content.",
  "Send reasoning_format=none so the server returns thinking tokens inline instead of extracting them into a separate field.": "Enviar reasoning_format=none para que el servidor devuelva tokens de pensamiento en línea.",
  "Pre-fill KV cache after response": "Pre-llenar caché KV tras respuesta",
  "After each response, re-submit the conversation to pre-fill the server KV cache. Makes the next turn faster since the prompt is already encoded while you read the response.": "Tras cada respuesta, reenviar la conversación para pre-llenar la caché KV. Acelera el siguiente turno.",
  "Conversation title": "Título de conversación",
  "Use first non-empty line for the conversation title": "Usar primera línea no vacía como título",
  "Generate title with LLM": "Generar título con LLM",
  "LLM title generation prompt": "Prompt de generación de título por LLM",
  "Optional template for the title generation prompt. Use {{USER}} for the user message and {{ASSISTANT}} for the assistant message.": "Plantilla opcional para el prompt de título. Usa {{USER}} y {{ASSISTANT}}.",
  "Choose how conversation titles are generated. The first non-empty line uses a fast deterministic rule; the LLM option uses a model-generated title from the first message exchange.": "Elige cómo se generan los títulos. La primera línea no vacía usa una regla rápida; la opción LLM usa un título generado por el modelo.",
  "Display generation statistics (tokens/second, token count, duration) below each assistant message.": "Mostrar estadísticas de generación (tokens/s, conteo, duración) bajo cada mensaje del asistente.",
  "Show toggle button to display messages as plain text instead of Markdown-formatted content": "Mostrar botón para ver mensajes como texto plano en vez de Markdown",
  "Automatically expand tool call details while executing and keep them expanded after completion.": "Expandir automáticamente detalles de llamadas a herramientas durante y tras la ejecución.",
  "Automatically show microphone button instead of send button when textarea is empty for models with audio modality support.": "Mostrar botón de micrófono en vez de enviar cuando el área de texto está vacía (modelos con audio).",
  "On pasting long text, it will be converted to a file. You can control the file length by setting the value of this parameter. Value 0 means disable.": "Al pegar texto largo se convierte en archivo. Controla la longitud con este parámetro. 0 desactiva.",
  "Use first non-empty line for the conversation title and synced.": "Usar primera línea no vacía como título y sincronizado.",
  "Counterpart of the conversation title radio; stored and synced without a dedicated UI field.": "Contraparte del radio de título; almacenado y sincronizado sin campo UI dedicado.",
  "Images larger than this will be resized before sending to server. Set to 0 to disable.": "Las imágenes más grandes se redimensionan antes de enviar. 0 desactiva.",
  "Maximum image resolution (megapixels)": "Resolución máxima de imagen (megapíxeles)",
  "Python interpreter enabled": "Intérprete Python activado",
  "Enable Python interpreter using Pyodide. Allows running Python code in markdown code blocks.": "Activar intérprete Python con Pyodide. Permite ejecutar código Python en bloques markdown.",
  "JavaScript sandbox tool": "Herramienta sandbox JavaScript",
  "Expose a run_javascript tool to the model. Code runs in a Web Worker inside a sandboxed iframe with an opaque origin, isolated from the WebUI and its API, with a hard timeout.": "Expone herramienta run_javascript al modelo. El código se ejecuta en Web Worker dentro de iframe aislado con timeout.",
  "Symbolic math (nerdamer)": "Matemática simbólica (nerdamer)",
  "Pre-load nerdamer in the sandbox for symbolic computation: simplify, diff, integrate, solve, and more. Requires \"JavaScript sandbox tool\" to be enabled.": "Precarga nerdamer en sandbox para cálculo simbólico: simplificar, derivar, integrar, resolver, etc. Requiere sandbox JS.",
  "Enable backend-based samplers. When enabled, supported samplers run on the accelerator backend for faster sampling.": "Activar muestreadores de backend para muestreo acelerado.",
  "Backend sampling": "Muestreo por backend",
