  "Addon for the temperature sampler. Smoothes out the probability redistribution based on the most probable token.": "Complemento del muestreador de temperatura. Suaviza la redistribución de probabilidad según el token más probable.",
  "Addon for the temperature sampler. The added value to the range of dynamic temperature, which adjusts probabilities by entropy of tokens.": "Complemento del muestreador de temperatura. Valor añadido al rango dinámico, ajusta probabilidades por entropía.",
  "Show microphone on empty input": "Mostrar micrófono en entrada vacía",
