  "Always show sidebar on desktop": "Mostrar siempre barra lateral en escritorio",
  "When copying a message with text attachments, combine them into a single plain text string instead of a special format that can be pasted back as attachments.": "Al copiar mensajes con adjuntos, combinarlos como texto plano en vez de formato especial.",
  "Display full raw model identifiers (e.g. \"ggml-org/GLM-4.7-Flash-GGUF:Q8_0\") instead of parsed names with badges.": "Mostrar identificadores completos del modelo en vez de nombres procesados con insignias.",
  "Display model tags (e.g. \"vision\", \"reasoning\") next to model names throughout the interface.": "Mostrar etiquetas de modelo (\"vision\", \"reasoning\") junto a los nombres en la interfaz.",
  "Display per-turn statistics (tokens, duration) under each turn in agentic responses. Shown only when \"Show message generation statistics\" is enabled.": "Mostrar estadísticas por turno (tokens, duración) en respuestas de agente. Solo si estadísticas de generación están activas.",
  "Enable \"Continue\" button for assistant messages, including reasoning models.": "Activar botón \"Continuar\" para mensajes del asistente, incluyendo modelos de razonamiento.",
  "The order at which samplers are applied, in simplified way. Default is \"top_k;typ_p;top_p;min_p;temperature\": top_k->typ_p->top_p->min_p->temperature": "Orden de aplicación de muestreadores. Por defecto: \"top_k;typ_p;top_p;min_p;temperature\".",
