  "When copying a message with text attachments, combine them into a single plain text string instead of a special format that can be pasted back as attachments.": "Lors de la copie d'un message avec pièces jointes, combiner en texte brut au lieu d'un format spécial.",
  "Display full raw model identifiers (e.g. \"ggml-org/GLM-4.7-Flash-GGUF:Q8_0\") instead of parsed names with badges.": "Afficher les identifiants complets du modèle au lieu des noms traités avec badges.",
  "Display model tags (e.g. \"vision\", \"reasoning\") next to model names throughout the interface.": "Afficher les étiquettes (\"vision\", \"reasoning\") à côté des noms de modèle dans l'interface.",
  "Display per-turn statistics (tokens, duration) under each turn in agentic responses. Shown only when \"Show message generation statistics\" is enabled.": "Afficher les stats par tour (tokens, durée) dans les réponses agentiques. Seulement si les stats de génération sont activées.",
