  "Set the API Key if you are using --api-key option for the server.": "サーバーで --api-key オプションを使用している場合は API キーを設定します。",
  "Parse PDF as image instead of text. Automatically falls back to text processing for non-vision models.": "PDF をテキストではなく画像として解析します。非ビジョンモデルでは自動的にテキスト処理にフォールバックします。",
  "Render user messages using markdown formatting in the chat.": "チャット内でユーザーメッセージを Markdown 形式でレンダリングします。",
  "Disable automatic scrolling while messages stream so you can control the viewport position manually.": "メッセージストリーミング中の自動スクロールを無効化し、ビューポート位置を手動で制御できるようにします。",
  "Display quantization badges (e.g. Q8_0, Q4_K_M) next to model names throughout the interface.": "インターフェース全体でモデル名の横に量子化バッジ（例: Q8_0、Q4_K_M）を表示します。",
  "DRY sampling reduces repetition in generated text even across long contexts. This parameter sets the DRY sampling multiplier.": "DRY サンプリングは長いコンテキストでも生成テキストの繰り返しを減らします。このパラメータは DRY サンプリング乗数を設定します。",
  "DRY sampling reduces repetition in generated text even across long contexts. This parameter sets the DRY sampling base value.": "DRY サンプリングは長いコンテキストでも生成テキストの繰り返しを減らします。このパラメータは DRY サンプリングのベース値を設定します。",
  "DRY sampling reduces repetition in generated text even across long contexts. This parameter sets the allowed length for DRY sampling.": "DRY サンプリングは長いコンテキストでも生成テキストの繰り返しを減らします。このパラメータは DRY サンプリングの許可長を設定します。",
  "DRY sampling reduces repetition in generated text even across long contexts. This parameter sets DRY penalty for the last n tokens.": "DRY サンプリングは長いコンテキストでも生成テキストの繰り返しを減らします。このパラメータは直近 n トークンへの DRY ペナルティを設定します。",
