  "Addon for the temperature sampler. Smoothes out the probability redistribution based on the most probable token.": "온도 샘플러용 애드온입니다. 가장 가능성 높은 토큰을 기준으로 확률 재분배를 부드럽게 합니다.",
  "Addon for the temperature sampler. The added value to the range of dynamic temperature, which adjusts probabilities by entropy of tokens.": "온도 샘플러용 애드온입니다. 토큰의 엔트로피에 따라 확률을 조정하는 동적 온도 범위에 더해지는 값입니다.",
  "Show microphone on empty input": "빈 입력에 마이크 표시",
  "Paste long text to file length": "긴 텍스트를 파일로 변환할 길이",
  "Show raw model names": "원시 모델 이름 표시",
  "Show model tags": "모델 태그 표시",
  "Show statistics for individual agentic turns": "개별 에이전트 턴 통계 표시",
  "Show thought in progress": "진행 중인 생각 표시",
  "Always show tool call content": "도구 호출 콘텐츠 항상 표시",
  "Use full height code blocks": "전체 높이 코드 블록 사용",
  "Always show sidebar on desktop": "데스크톱에서 항상 사이드바 표시",
  "When copying a message with text attachments, combine them into a single plain text string instead of a special format that can be pasted back as attachments.": "텍스트 첨부가 있는 메시지를 복사할 때 첨부로 다시 붙여넣을 수 있는 특수 형식 대신 단일 일반 텍스트 문자열로 결합합니다.",
  "Display full raw model identifiers (e.g. \"ggml-org/GLM-4.7-Flash-GGUF:Q8_0\") instead of parsed names with badges.": "배지가 있는 파싱된 이름 대신 전체 원시 모델 식별자(예: \"ggml-org/GLM-4.7-Flash-GGUF:Q8_0\")를 표시합니다.",
  "Display model tags (e.g. \"vision\", \"reasoning\") next to model names throughout the interface.": "인터페이스 전체에서 모델 이름 옆에 모델 태그(예: \"vision\", \"reasoning\")를 표시합니다.",
  "Display per-turn statistics (tokens, duration) under each turn in agentic responses. Shown only when \"Show message generation statistics\" is enabled.": "에이전트 응답의 각 턴 아래에 통계(토큰, 소요 시간)를 표시합니다. '메시지 생성 통계 표시'가 활성화된 경우에만 표시됩니다.",
  "Enable \"Continue\" button for assistant messages, including reasoning models.": "추론 모델을 포함한 어시스턴트 메시지에 '계속' 버튼을 활성화합니다.",
  "The order at which samplers are applied, in simplified way. Default is \"top_k;typ_p;top_p;min_p;temperature\": top_k->typ_p->top_p->min_p->temperature": "샘플러가 적용되는 순서(간단한 형태). 기본값: \"top_k;typ_p;top_p;min_p;temperature\": top_k->typ_p->top_p->min_p->temperature",
