  "Code copied": "코드가 복사되었습니다",
  "Message copied": "메시지가 복사되었습니다",
  "Set the API Key if you are using --api-key option for the server.": "서버에서 --api-key 옵션을 사용하는 경우 API 키를 설정하세요.",
  "Parse PDF as image instead of text. Automatically falls back to text processing for non-vision models.": "PDF를 텍스트 대신 이미지로 파싱합니다. 비전 모델이 아닌 경우 자동으로 텍스트 처리로 대체됩니다.",
  "Render user messages using markdown formatting in the chat.": "채팅에서 사용자 메시지를 Markdown 형식으로 렌더링합니다.",
  "Disable automatic scrolling while messages stream so you can control the viewport position manually.": "메시지 스트리밍 중 자동 스크롤을 비활성화하여 뷰포트 위치를 수동으로 제어할 수 있습니다.",
  "Display quantization badges (e.g. Q8_0, Q4_K_M) next to model names throughout the interface.": "인터페이스 전체에서 모델 이름 옆에 양자화 배지(예: Q8_0, Q4_K_M)를 표시합니다.",
  "DRY sampling reduces repetition in generated text even across long contexts. This parameter sets the DRY sampling multiplier.": "DRY 샘플링은 긴 컨텍스트에서도 생성 텍스트의 반복을 줄입니다. 이 매개변수는 DRY 샘플링 승수를 설정합니다.",
  "DRY sampling reduces repetition in generated text even across long contexts. This parameter sets the DRY sampling base value.": "DRY 샘플링은 긴 컨텍스트에서도 생성 텍스트의 반복을 줄입니다. 이 매개변수는 DRY 샘플링 기준값을 설정합니다.",
  "DRY sampling reduces repetition in generated text even across long contexts. This parameter sets the allowed length for DRY sampling.": "DRY 샘플링은 긴 컨텍스트에서도 생성 텍스트의 반복을 줄입니다. 이 매개변수는 DRY 샘플링 허용 길이를 설정합니다.",
  "DRY sampling reduces repetition in generated text even across long contexts. This parameter sets DRY penalty for the last n tokens.": "DRY 샘플링은 긴 컨텍스트에서도 생성 텍스트의 반복을 줄입니다. 이 매개변수는 최근 n개 토큰에 대한 DRY 페널티를 설정합니다.",
  "No tools available": "사용 가능한 도구가 없습니다",
  "Conversations": "대화",
  "Download your conversations as a ZIP of JSONL files. This includes all messages, attachments, and conversation history.": "대화를 JSONL 파일의 ZIP으로 다운로드합니다. 모든 메시지, 첨부 파일, 대화 기록이 포함됩니다.",
  "Export conversations": "대화 내보내기",
  "Import one or more conversations from a previously exported ZIP or JSONL file. This will merge with your existing conversations.": "이전에 내보낸 ZIP 또는 JSONL 파일에서 하나 이상의 대화를 가져옵니다. 기존 대화와 병합됩니다.",
  "Import conversations": "대화 가져오기",
  "Delete all": "모두 삭제",
  "Permanently delete all conversations and their messages. This action cannot be undone. Consider exporting your conversations first if you want to keep a backup.": "모든 대화와 해당 메시지를 영구 삭제합니다. 이 작업은 되돌릴 수 없습니다. 백업을 유지하려면 먼저 대화를 내보내는 것이 좋습니다.",
  "Delete all conversations": "모든 대화 삭제",
  "Export your chat settings and preferences as a JSON file.": "채팅 설정과 환경 설정을 JSON 파일로 내보냅니다.",
  "Export settings": "설정 내보내기",
  "Import chat settings from a previously exported JSON file. This will merge with your existing settings.": "이전에 내보낸 JSON 파일에서 채팅 설정을 가져옵니다. 기존 설정과 병합됩니다.",
