  "Display quantization badges (e.g. Q8_0, Q4_K_M) next to model names throughout the interface.": "Exibir selos de quantização (ex.: Q8_0, Q4_K_M) ao lado dos nomes dos modelos em toda a interface.",
  "DRY sampling reduces repetition in generated text even across long contexts. This parameter sets the DRY sampling multiplier.": "A amostragem DRY reduz a repetição no texto gerado mesmo em contextos longos. Este parâmetro define o multiplicador da amostragem DRY.",
  "DRY sampling reduces repetition in generated text even across long contexts. This parameter sets the DRY sampling base value.": "A amostragem DRY reduz a repetição no texto gerado mesmo em contextos longos. Este parâmetro define o valor base da amostragem DRY.",
  "DRY sampling reduces repetition in generated text even across long contexts. This parameter sets the allowed length for DRY sampling.": "A amostragem DRY reduz a repetição no texto gerado mesmo em contextos longos. Este parâmetro define o comprimento permitido para a amostragem DRY.",
  "DRY sampling reduces repetition in generated text even across long contexts. This parameter sets DRY penalty for the last n tokens.": "A amostragem DRY reduz a repetição no texto gerado mesmo em contextos longos. Este parâmetro define a penalidade DRY para os últimos n tokens.",
