  "DRY sampling reduces repetition in generated text even across long contexts. This parameter sets the DRY sampling base value.": "Il campionamento DRY riduce le ripetizioni nel testo generato anche su contesti lunghi. Questo parametro imposta il valore base del campionamento DRY.",
  "DRY sampling reduces repetition in generated text even across long contexts. This parameter sets the allowed length for DRY sampling.": "Il campionamento DRY riduce le ripetizioni nel testo generato anche su contesti lunghi. Questo parametro imposta la lunghezza consentita per il campionamento DRY.",
  "DRY sampling reduces repetition in generated text even across long contexts. This parameter sets DRY penalty for the last n tokens.": "Il campionamento DRY riduce le ripetizioni nel testo generato anche su contesti lunghi. Questo parametro imposta la penalità DRY per gli ultimi n token.",
