  "DRY sampling reduces repetition in generated text even across long contexts. This parameter sets the DRY sampling multiplier.": "DRY örneklemesi, uzun bağlamlarda bile üretilen metindeki tekrarı azaltır. Bu parametre DRY örnekleme çarpanını ayarlar.",
