  "DRY sampling reduces repetition in generated text even across long contexts. This parameter sets the allowed length for DRY sampling.": "DRY örneklemesi, uzun bağlamlarda bile üretilen metindeki tekrarı azaltır. Bu parametre DRY örnekleme için izin verilen uzunluğu ayarlar.",
  "DRY sampling reduces repetition in generated text even across long contexts. This parameter sets DRY penalty for the last n tokens.": "DRY örneklemesi, uzun bağlamlarda bile üretilen metindeki tekrarı azaltır. Bu parametre son n token için DRY cezasını ayarlar.",
