  "Export conversations": "Sohbetleri dışa aktar",
  "Import one or more conversations from a previously exported ZIP or JSONL file. This will merge with your existing conversations.": "Önceden dışa aktarılmış bir ZIP veya JSONL dosyasından bir veya daha fazla sohbeti içe aktarın. Mevcut sohbetlerinizle birleştirilir.",
