  "Set the API Key if you are using --api-key option for the server.": "Ustaw klucz API, jeśli używasz opcji --api-key dla serwera.",
  "Parse PDF as image instead of text. Automatically falls back to text processing for non-vision models.": "Parsuj PDF jako obraz zamiast tekstu. Automatycznie przechodzi na przetwarzanie tekstu dla modeli bez wizji.",
  "Render user messages using markdown formatting in the chat.": "Renderuj wiadomości użytkownika z formatowaniem Markdown na czacie.",
  "Disable automatic scrolling while messages stream so you can control the viewport position manually.": "Wyłącz automatyczne przewijanie podczas strumieniowania wiadomości, aby ręcznie kontrolować pozycję widoku.",
  "Display quantization badges (e.g. Q8_0, Q4_K_M) next to model names throughout the interface.": "Wyświetlaj odznaki kwantyzacji (np. Q8_0, Q4_K_M) obok nazw modeli w całym interfejsie.",
  "DRY sampling reduces repetition in generated text even across long contexts. This parameter sets the DRY sampling multiplier.": "Próbkowanie DRY ogranicza powtarzalność generowanego tekstu nawet w długich kontekstach. Ten parametr ustawia mnożnik próbkowania DRY.",
  "DRY sampling reduces repetition in generated text even across long contexts. This parameter sets the DRY sampling base value.": "Próbkowanie DRY ogranicza powtarzalność generowanego tekstu nawet w długich kontekstach. Ten parametr ustawia wartość bazową próbkowania DRY.",
  "DRY sampling reduces repetition in generated text even across long contexts. This parameter sets the allowed length for DRY sampling.": "Próbkowanie DRY ogranicza powtarzalność generowanego tekstu nawet w długich kontekstach. Ten parametr ustawia dozwoloną długość próbkowania DRY.",
  "DRY sampling reduces repetition in generated text even across long contexts. This parameter sets DRY penalty for the last n tokens.": "Próbkowanie DRY ogranicza powtarzalność generowanego tekstu nawet w długich kontekstach. Ten parametr ustawia karę DRY za ostatnie n tokenów.",
  "No tools available": "Brak dostępnych narzędzi",
  "Conversations": "Rozmowy",
  "Download your conversations as a ZIP of JSONL files. This includes all messages, attachments, and conversation history.": "Pobierz swoje rozmowy jako ZIP plików JSONL. Obejmuje wszystkie wiadomości, załączniki i historię rozmów.",
  "Export conversations": "Eksportuj rozmowy",
  "Import one or more conversations from a previously exported ZIP or JSONL file. This will merge with your existing conversations.": "Zaimportuj jedną lub więcej rozmów z wcześniej wyeksportowanego pliku ZIP lub JSONL. Zostaną połączone z istniejącymi rozmowami.",
  "Import conversations": "Importuj rozmowy",
